func Nuevo(sector int) (Documento, error) {
	switch sector {
	case 1:
		return &CompraVenta{}, nil
	case 2:
		return &Alquiler{}, nil
	case 11:
		return &Educativo{}, nil
	case 13:
		return &ServicioBasico{}, nil
	case 28:
		return &ExportacionServicios{}, nil
	case 34:
		return &Seguros{}, nil
	case 14:
		return &AlcanzadaICE{}, nil
	case 16:
		return &Hotel{}, nil
	case 17:
		return &Hospital{}, nil
	case 24:
		return &NotaCreditoDebito{}, nil
	case 48:
		return &NotaCreditoDebitoICE{}, nil
	default:
		return nil, fmt.Errorf("sector V3 no soportado: %d", sector)
	}
}
